#include <bits/stdc++.h>

using namespace std;

using i64 = long long;

const i64 MOD = 1000000007;

struct F {
  i64 v;
  F(i64 x = 0) : v(x % MOD) {
    if (v < 0) v += MOD;
    if (v >= MOD) { cerr << "F error\n"; exit(1); }
  }
  F operator+(const F& o) const { return F((v + o.v) % MOD); }
  F operator-(const F& o) const { return F((v - o.v + MOD) % MOD); }
  F operator*(const F& o) const { return F((v * o.v) % MOD); }
  F operator/(const F& o) const { return (*this) * o.inv(); }
  F& operator+=(const F& o) { v = (v + o.v) % MOD; return *this; }
  F& operator-=(const F& o) { v = (v - o.v + MOD) % MOD; return *this; }
  F& operator*=(const F& o) { v = (v * o.v) % MOD; return *this; }
  F& operator/=(const F& o) { return (*this) *= o.inv(); }
  F inv() const {
    i64 e = MOD - 2, b = v, r = 1;
    while (e) {
      if (e & 1) r = (r * b) % MOD;
      b = (b * b) % MOD;
      e >>= 1;
    }
    return Field(r);
  }
};

template<typename T>
vector<vector<T>> multiply(const vector<vector<T>>& A, const vector<vector<T>>& B) {
  int n = A.size(), m = A[0].size(), p = B[0].size();
  if (B.size() != m) { cerr << "multiply dim error\n"; exit(1); }
  vector<vector<T>> C(n, vector<T>(p));
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < p; ++j)
      for (int k = 0; k < m; ++k)
        C[i][j] = C[i][j] + A[i][k] * B[k][j];
  return C;
}

template<typename T>
vector<T> multiply(const vector<vector<T>>& A, const vector<T>& x) {
  int n = A.size(), m = A[0].size();
  if (x.size() != m) { cerr << "multiply vec dim error\n"; exit(1); }
  vector<T> y(n);
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j)
      y[i] = y[i] + A[i][j] * x[j];
  return y;
}

template<typename T>
vector<vector<T>> make2D(int r, int c, const T& val = T()) {
  return vector<vector<T>>(r, vector<T>(c, val));
}

template<typename T>
vector<vector<vector<T>>> make3D(int a, int b, int c, const T& val = T()) {
  return vector<vector<vector<T>>>(a, vector<vector<T>>(b, vector<T>(c, val)));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  i64 n;
  int d;
  cin >> n >> d;

  auto shift = make3D<F>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d; ++i)
      shift[k][i][(i + k) % d] = F(1);
    shift[k][d][d] = F(1);
  }

  auto unit = make3D<F>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d + 1; ++i)
      unit[k][i][i] = F(1);
    for (int i = 0; i < d + 1; ++i)
      unit[k][k][i] = F(1);
  }

  auto I = make2D<F>(d + 1, d + 1);
  for (int i = 0; i < d + 1; ++i)
    I[i][i] = F(1);

  unordered_map<i64, vector<vector<F>>> dp;

  function<vector<vector<F>>(i64)> compute = [&](i64 p) -> vector<vector<F>> {
    auto it = dp.find(p);
    if (it != dp.end()) return it->second;
    if (p <= d) {
      auto M = I;
      for (int k = 0; k < p; ++k)
        M = multiply(unit[k], M);
      return M;
    }
    i64 block = d;
    while ((p + block - 1) / block > d) block *= d;
    auto child = compute(block);
    auto M = child;
    i64 rem = p - block;
    for (int k = 1; k < d; ++k) {
      if (rem >= block) {
        M = multiply(multiply(multiply(shift[d - k], child), shift[k]), M);
        rem -= block;
      } else if (rem > 0) {
        M = multiply(multiply(multiply(shift[d - k], compute(rem)), shift[k]), M);
        rem = 0;
      } else break;
    }
    return dp[p] = M;
  };

  auto M = compute(n);
  vector<F> base(d + 1);
  base[d] = F(1);
  auto result = multiply(M, base);
  F total;
  for (auto& x : result) total += x;
  cout << total.v << '\n';
}
